const runtime="<script id=\"b153-pwa-runtime\">(function(){'use strict';\nconst div=document.createElement('section');div.id='b153PWA';div.setAttribute('aria-label','Instalação e estado offline da Demo PWA');\nconst desc=document.createElement('div');desc.className='b153-desc';\nconst title=document.createElement('strong');title.textContent='BTC STRATEGY PRO V20 · BETA QA';\nconst status=document.createElement('span');status.id='b153Status';status.setAttribute('role','status');\ndesc.append(title,status);\nconst actions=document.createElement('div');actions.className='b153-action';\nconst install=document.createElement('button');install.id='b153Install';install.type='button';install.textContent='Instalar Demo';\nconst info=document.createElement('button');info.id='b153OfflineHelp';info.type='button';info.textContent='Como testar offline';\nactions.append(install,info);div.append(desc,actions);\nconst target=document.getElementById('b13Labs'),main=document.querySelector('main');\nif(target?.parentNode)target.parentNode.insertBefore(div,target);\nelse if(main)main.prepend(div);else document.body.prepend(div);\nlet promptEvent=null,reg=null,installed=false,effectiveOnline=navigator.onLine,checkGeneration=0;\nconst inStandalone=()=>matchMedia('(display-mode: standalone)').matches;\nfunction update(){status.textContent='Ligação: '+(effectiveOnline?'online':'offline')+' · '+(inStandalone()||installed?'PWA instalada':'Demo de teste; instalação requer HTTPS/localhost')+' · não usar saldos reais';install.hidden=inStandalone()||installed;}\nasync function checkConnectivity(){\n const gen=++checkGeneration;\n try{\n  // This file is not in CacheStorage: it proves a real same-origin connection, no private data.\n  const r=await fetch('./connectivity-probe.txt?t='+Date.now(),{cache:'no-store',credentials:'omit'});\n  if(gen===checkGeneration)effectiveOnline=r.ok;\n }catch(e){if(gen===checkGeneration)effectiveOnline=false;}\n update();\n}\nwindow.addEventListener('online',()=>{effectiveOnline=true;update();checkConnectivity();});\nwindow.addEventListener('offline',()=>{effectiveOnline=false;update();});\nwindow.addEventListener('pageshow',checkConnectivity);\nwindow.addEventListener('focus',checkConnectivity);\nwindow.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;update();});\nwindow.addEventListener('appinstalled',()=>{installed=true;promptEvent=null;update();});\ninstall.addEventListener('click',async()=>{if(inStandalone()||installed)return;\n if(promptEvent){const event=promptEvent;promptEvent=null;try{await event.prompt();await event.userChoice;}catch(e){status.textContent='Instalação indisponível; usa o menu do Chrome.';}}else{\n status.textContent='Chrome Android: menu ⋮ → Instalar app. Usa HTTPS para permitir a instalação.';}});\ninfo.addEventListener('click',()=>{status.textContent='Abre primeiro a Demo online, depois desliga Wi-Fi/dados móveis e reabre a PWA. Só dados fictícios.';});\nasync function register(){if(!('serviceWorker' in navigator)||!(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){update();return;}\n try{reg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});await navigator.serviceWorker.ready;}\n catch(e){status.textContent='Offline ainda não disponível neste navegador. Verifica HTTPS.';}}\nwindow.addEventListener('load',register);update();\nwindow.BTCB153PWA=Object.freeze({state:()=>({online:effectiveOnline,installed:inStandalone()||installed,registered:!!reg,\n scope:reg?.scope||null,networkCheckUsesStaticProbe:true,accountDataUsed:false,livePriceUsed:false,ordersEnabled:false})});\n})();</script>";
